(() => {
  // javascript/top/top-navigation.js
  var DisclosureNav = class {
    constructor(domNode) {
      this.rootNode = domNode;
      this.timers = [];
      this.controlledNodes = [];
      this.openIndex = null;
      this.useArrowKeys = true;
      this.desktopQuery = window.matchMedia("(min-width: 768px)");
      this.topLevelNodes = [
        ...this.rootNode.querySelectorAll(
          ".main-link, button[aria-expanded]"
          // '.main-link, button[aria-expanded][aria-controls]'
        )
      ];
      domNode.classList.add("loaded");
      this.topLevelNodes.forEach((node) => {
        if (node.tagName.toLowerCase() === "button" && node.hasAttribute("aria-controls")) {
          const menu = node.parentNode.querySelector(".sub-menu-wrap");
          if (menu) {
            var li = node.closest("li");
            this.controlledNodes.push(menu);
            node.setAttribute("aria-expanded", "false");
            this.toggleMenu(menu, false);
            menu.addEventListener(
              "keydown",
              this.onMenuKeyDown.bind(this)
            );
            node.addEventListener(
              "click",
              this.onButtonClick.bind(this)
            );
            node.addEventListener(
              "keydown",
              this.onButtonKeyDown.bind(this)
            );
            li.addEventListener(
              "mouseover",
              this.onMouseOver.bind(this)
            );
            li.addEventListener("mouseout", this.onMouseOut.bind(this));
          }
        } else {
          this.controlledNodes.push(null);
          node.addEventListener("keydown", this.onLinkKeyDown.bind(this));
        }
      });
      this.rootNode.addEventListener("focusout", this.onBlur.bind(this));
    }
    controlFocusByKey(keyboardEvent, nodeList, currentIndex) {
      switch (keyboardEvent.key) {
        case "ArrowUp":
        case "ArrowLeft":
          keyboardEvent.preventDefault();
          if (currentIndex > -1) {
            var prevIndex = Math.max(0, currentIndex - 1);
            nodeList[prevIndex].focus();
          }
          break;
        case "ArrowDown":
        case "ArrowRight":
          keyboardEvent.preventDefault();
          if (currentIndex > -1) {
            var nextIndex = Math.min(
              nodeList.length - 1,
              currentIndex + 1
            );
            nodeList[nextIndex].focus();
          }
          break;
        case "Home":
          keyboardEvent.preventDefault();
          nodeList[0].focus();
          break;
        case "End":
          keyboardEvent.preventDefault();
          nodeList[nodeList.length - 1].focus();
          break;
      }
    }
    // public function to close open menu
    close() {
      this.toggleExpand(this.openIndex, false);
    }
    onBlur(event) {
      var menuContainsFocus = this.rootNode.contains(event.relatedTarget);
      if (!menuContainsFocus && this.openIndex !== null) {
        this.toggleExpand(this.openIndex, false);
      }
    }
    onMouseOver(event) {
      if (this.desktopQuery.matches) {
        var button = event.currentTarget.querySelector(
          "button[aria-expanded][aria-controls]"
        );
        var buttonIndex = this.topLevelNodes.indexOf(button);
        clearTimeout(this.timers[buttonIndex]);
        this.toggleExpand(buttonIndex, true);
      }
    }
    onMouseOut(event) {
      if (this.desktopQuery.matches) {
        var button = event.currentTarget.querySelector(
          "button[aria-expanded][aria-controls]"
        );
        var buttonIndex = this.topLevelNodes.indexOf(button);
        this.timers[buttonIndex] = setTimeout(this.close.bind(this), 1e3);
      }
    }
    onButtonClick(event) {
      var button = event.target;
      var buttonIndex = this.topLevelNodes.indexOf(button);
      var buttonExpanded = button.getAttribute("aria-expanded") === "true";
      this.toggleExpand(buttonIndex, !buttonExpanded);
    }
    onButtonKeyDown(event) {
      var targetButtonIndex = this.topLevelNodes.indexOf(
        document.activeElement
      );
      if (event.key === "Escape") {
        this.toggleExpand(this.openIndex, false);
      } else if (this.useArrowKeys && this.openIndex === targetButtonIndex && event.key === "ArrowDown") {
        event.preventDefault();
        this.controlledNodes[this.openIndex].querySelector("a").focus();
      } else if (this.useArrowKeys) {
        this.controlFocusByKey(
          event,
          this.topLevelNodes,
          targetButtonIndex
        );
      }
    }
    onLinkKeyDown(event) {
      var targetLinkIndex = this.topLevelNodes.indexOf(
        document.activeElement
      );
      if (this.useArrowKeys) {
        this.controlFocusByKey(event, this.topLevelNodes, targetLinkIndex);
      }
    }
    onMenuKeyDown(event) {
      if (this.openIndex === null) {
        return;
      }
      var menuLinks = Array.prototype.slice.call(
        this.controlledNodes[this.openIndex].querySelectorAll("a")
      );
      var currentIndex = menuLinks.indexOf(document.activeElement);
      if (event.key === "Escape") {
        this.topLevelNodes[this.openIndex].focus();
        this.toggleExpand(this.openIndex, false);
      } else if (this.useArrowKeys) {
        this.controlFocusByKey(event, menuLinks, currentIndex);
      }
    }
    toggleExpand(index, expanded) {
      if (this.openIndex !== index) {
        this.toggleExpand(this.openIndex, false);
      }
      if (this.topLevelNodes[index]) {
        this.openIndex = expanded ? index : null;
        this.topLevelNodes[index].setAttribute("aria-expanded", expanded);
        this.toggleMenu(this.controlledNodes[index], expanded);
      }
    }
    toggleMenu(domNode, show) {
      if (domNode) {
        domNode.style.display = show ? "block" : "none";
      }
    }
    updateKeyControls(useArrowKeys) {
      this.useArrowKeys = useArrowKeys;
    }
  };
  window.addEventListener(
    "load",
    function() {
      var menus = document.querySelectorAll(".disclosure-nav");
      var disclosureMenus = [];
      for (var i = 0; i < menus.length; i++) {
        disclosureMenus[i] = new DisclosureNav(menus[i]);
      }
    },
    false
  );
  document.addEventListener("DOMContentLoaded", () => {
    var focusedButtons = [];
    var navButtons = document.querySelectorAll(".open-on-focus button");
    navButtons.forEach(function(item) {
      item.addEventListener("focus", function(e) {
        setTimeout(() => {
          focusedButtons.push(item);
        }, "100");
      });
      item.addEventListener("blur", function(e) {
        focusedButtons.splice(focusedButtons.indexOf(item), 1);
      });
      item.addEventListener(
        "click",
        function(e) {
          if (focusedButtons.includes(item)) {
            document.activeElement.blur();
          }
        },
        false
      );
    });
  });
  document.addEventListener("DOMContentLoaded", () => {
    var mainMenu = document.getElementById("pageHeader").querySelector("nav");
    document.getElementById("mobile-menu-toggle").addEventListener(
      "click",
      function(e) {
        var navWrapper = document.getElementsByClassName("nav-wrapper")[0];
        var toggleBtn = mainMenu.querySelector("#mobile-menu-toggle");
        if (navWrapper.classList.contains("open")) {
          navWrapper.classList.remove("open");
          toggleBtn.ariaExpanded = "false";
        } else {
          navWrapper.classList.add("open");
          toggleBtn.ariaExpanded = "true";
        }
        e.stopImmediatePropagation();
      },
      false
    );
  });

  // javascript/top/sticky-header.js
  var prevScrollpos = -1;
  var scrollThreshhold = 15;
  window.onscroll = function() {
    checkScrollPosition();
  };
  function checkScrollPosition() {
    var currentScrollPos = window.pageYOffset;
    var diff = prevScrollpos - currentScrollPos;
    if (currentScrollPos <= 0) {
      if (document.body.classList.contains("scrolled")) {
        document.body.classList.remove("scrolled");
      }
    } else if (currentScrollPos > 156) {
      if (!document.body.classList.contains("scrolled")) {
        document.body.classList.add("scrolled");
      }
    }
    if (prevScrollpos < 0 || currentScrollPos <= 0 || diff > scrollThreshhold) {
      if (document.body.classList.contains("scrolling-down")) {
        document.body.classList.remove("scrolling-down");
      }
    } else if (diff < scrollThreshhold * -1) {
      if (!document.body.classList.contains("scrolling-down")) {
        document.body.classList.add("scrolling-down");
        var navWrapper = document.getElementsByClassName("nav-wrapper")[0];
        var toggleBtn = document.querySelector("#mobile-menu-toggle");
        navWrapper.classList.remove("open");
        toggleBtn.ariaExpanded = "false";
      }
    }
    prevScrollpos = currentScrollPos;
  }
})();
